<?php
namespace ServSys\PreventiveMaintenance;
use ServSys\Companies\CompanyContext;
if(!defined('ABSPATH')){exit;}
final class PMAgreementRepository {
 private $wpdb;private $table;
 public function __construct($wpdb=null){$this->wpdb=$wpdb?:$GLOBALS['wpdb'];$this->table=$this->wpdb->prefix.'servsys_pm_agreements';}
 public function find(int $id){$wpdb=$this->wpdb;/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Plugin-owned PM agreement data. */return $wpdb->get_row($wpdb->prepare('SELECT * FROM %i WHERE id = %d AND company_id = %d',$this->table,$id,CompanyContext::current_company_id()),ARRAY_A);}
 public function for_customer(int $customer_id): array {$wpdb=$this->wpdb;/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Plugin-owned PM agreement data. */return $wpdb->get_results($wpdb->prepare('SELECT * FROM %i WHERE customer_id = %d AND company_id = %d ORDER BY start_date DESC,id DESC',$this->table,$customer_id,CompanyContext::current_company_id()),ARRAY_A);}
 public function search(string $term=''): array {$wpdb=$this->wpdb;$cid=CompanyContext::current_company_id();$customers=$this->wpdb->prefix.'servsys_customers';$sites=$this->wpdb->prefix.'servsys_sites';$like='%'.$this->wpdb->esc_like($term).'%';if(''===$term){$sql=$wpdb->prepare('SELECT a.*,c.name customer_name,s.name site_name,s.address1 site_address FROM %i a JOIN %i c ON c.id=a.customer_id JOIN %i s ON s.id=a.site_id WHERE a.company_id=%d ORDER BY a.start_date DESC,a.id DESC LIMIT 250',$this->table,$customers,$sites,$cid);}else{$sql=$wpdb->prepare('SELECT a.*,c.name customer_name,s.name site_name,s.address1 site_address FROM %i a JOIN %i c ON c.id=a.customer_id JOIN %i s ON s.id=a.site_id WHERE a.company_id=%d AND (c.name LIKE %s OR s.name LIKE %s OR s.address1 LIKE %s OR a.plan_description_snapshot LIKE %s) ORDER BY a.start_date DESC,a.id DESC LIMIT 250',$this->table,$customers,$sites,$cid,$like,$like,$like,$like);}/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Plugin-owned PM agreement data. *//* phpcs:ignore WordPress.DB.PreparedSQL.NotPrepared -- $sql is produced exclusively by $wpdb->prepare() in the branches above. */return $wpdb->get_results($sql,ARRAY_A);}
 public function create(array $data): int {$data['company_id']=CompanyContext::current_company_id();$this->wpdb->insert($this->table,$data);return (int)$this->wpdb->insert_id;}
 public function update(int $id,array $data): bool {return false!==$this->wpdb->update($this->table,$data,array('id'=>$id,'company_id'=>CompanyContext::current_company_id()));}
}
